#include "vtf_texture_layout.h"
#include <fstream>
#include <iostream>
#include <filesystem>
std::vector<uint8_t>read(const std::filesystem::path&p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("texture missing");return {(std::istreambuf_iterator<char>(f)),{}};}
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");std::vector<uint8_t>data(104);auto put=[&](size_t o,uint32_t v){std::memcpy(data.data()+o,&v,4);};auto half=[&](size_t o,uint16_t v){std::memcpy(data.data()+o,&v,2);};put(0,0x00465456);put(4,7);put(8,2);put(12,80);half(16,4);half(18,4);half(24,1);half(63,1);put(52,13);data[56]=3;auto layout=readVtfTextureLayoutCandidate(data);if(layout.mips.size()!=3||layout.mips[2].offset!=80||layout.mips[1].offset!=88||layout.mips[0].offset!=96||layout.mips[0].size!=8)throw std::runtime_error("mip order");unsigned rejected=0;for(size_t n=0;n<data.size();++n){bool failed=false;try{readVtfTextureLayoutCandidate({data.begin(),data.begin()+n});}catch(const std::runtime_error&){failed=true;}if(!failed)throw std::runtime_error("truncation accepted");++rejected;}
 for(auto edit:std::vector<std::pair<size_t,uint32_t>>{{8,3},{12,64},{20,0x4000},{52,999}}){auto bad=data;std::memcpy(bad.data()+edit.first,&edit.second,4);bool failed=false;try{readVtfTextureLayoutCandidate(bad);}catch(const std::runtime_error&){failed=true;}if(!failed)throw std::runtime_error("bad VTF accepted");++rejected;}
 if(argc!=2)throw std::runtime_error("texture directory required");for(auto&name:std::vector<std::string>{"armor","head","visor","eyes","transparenteyes","fluff","bodysfw","visorglow"}){auto bytes=read(std::filesystem::path(argv[1])/(name+".vtf"));auto real=readVtfTextureLayoutCandidate(bytes);std::cout<<name<<" format="<<real.format<<" dimensions="<<real.mips[0].width<<'x'<<real.mips[0].height<<" mips="<<real.mips.size()<<" payload_verified="<<bytes.size()<<'\n';}std::cout<<"x64 VTF mip layout passed textures=8 rejected="<<rejected<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
